// Applies the SQL migrations of drizzle/ (generated by `pnpm db:generate`), at the server's start and by `pnpm db:migrate`.
// Under an advisory lock: two servers (or a server and the console) starting together don't migrate twice.
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { drizzle } from 'drizzle-orm/postgres-js';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import postgres from 'postgres';

export const MIGRATIONS = join(dirname(fileURLToPath(import.meta.url)), '../../drizzle');
const LOCK = 7_272_741;

/** On a client of its own with one connection: the advisory lock belongs to that connection. */
export async function runMigrations(url: string) {
  const one = postgres(url, { max: 1, onnotice: () => {} });
  try {
    await one`select pg_advisory_lock(${LOCK})`;
    await migrate(drizzle(one), { migrationsFolder: MIGRATIONS });
    await one`select pg_advisory_unlock(${LOCK})`;
  } finally { await one.end(); }
}
